const clock = new THREE.Clock();
scene.background = new THREE.Color(0xe8f0f5);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Atmospheric depth cues
scene.fog = new THREE.FogExp2(0xe8f0f5, 0.018);

// Cinematic lighting rig
const sunLight = new THREE.DirectionalLight(0xfff8f0, 1.45);
sunLight.position.set(25, 35, 20);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 0.1;
sunLight.shadow.camera.far = 100;
sunLight.shadow.camera.left = -40;
sunLight.shadow.camera.right = 40;
sunLight.shadow.camera.top = 40;
sunLight.shadow.camera.bottom = -40;
sunLight.shadow.bias = -0.0001;

const skyFill = new THREE.DirectionalLight(0xcce8ff, 0.65);
skyFill.position.set(-20, 15, 10);

const ambient = new THREE.AmbientLight(0x6b7c94, 0.35);

const cityGlow = new THREE.PointLight(0x4d9fff, 0.9, 50);
cityGlow.position.set(0, 20, 0);

scene.add(sunLight, skyFill, ambient, cityGlow);

const cityGroup = new THREE.Group();
scene.add(cityGroup);

// Premium materials
const buildingMat = new THREE.MeshStandardMaterial({
  color: 0xeef2f7,
  roughness: 0.25,
  metalness: 0.75
});

const darkBuildingMat = new THREE.MeshStandardMaterial({
  color: 0xc5d0dc,
  roughness: 0.35,
  metalness: 0.6
});

const windowMat = new THREE.MeshStandardMaterial({
  color: 0x1a3a5c,
  emissive: 0x4d9fff,
  emissiveIntensity: 1.2,
  roughness: 0.2,
  metalness: 0.9
});

// Helper to create spherical city layers
function createCitySphere(radius, count, heightScale, material, yOffset = 0) {
  const geo = new THREE.BoxGeometry(1, 1, 1);
  // Handle both old Geometry API and new BufferGeometry API
  if (geo.attributes && geo.attributes.position) {
    // BufferGeometry path
    const positions = geo.attributes.position.array;
    for (let i = 1; i < positions.length; i += 3) {
      positions[i] += 0.5;
    }
    geo.attributes.position.needsUpdate = true;
  } else if (geo.vertices) {
    // Old Geometry path
    for (let i = 0; i < geo.vertices.length; i++) {
      geo.vertices[i].y += 0.5;
    }
    geo.verticesNeedUpdate = true;
  }

  const mesh = new THREE.InstancedMesh(geo, material, count);
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  const dummy = new THREE.Object3D();
  const color = new THREE.Color();

  for (let i = 0; i < count; i++) {
    const phi = Math.acos(-1 + (2 * i) / count);
    const theta = Math.sqrt(count * Math.PI) * phi;

    const x = radius * Math.cos(theta) * Math.sin(phi);
    const z = radius * Math.sin(theta) * Math.sin(phi);
    const y = radius * Math.cos(phi) + yOffset;

    const height = 0.4 + Math.random() * heightScale;
    const width = 0.2 + Math.random() * 0.5;

    dummy.position.set(x, y, z);
    dummy.scale.set(width, height, width);
    dummy.lookAt(0, y, 0);
    dummy.rotateX(-Math.PI / 2);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);

    const shade = 0.9 + Math.random() * 0.1;
    color.setHex(0xeef2f7);
    color.multiplyScalar(shade);
    mesh.setColorAt(i, color);
  }

  return mesh;
}

// Layered city composition
const distantLayer = createCitySphere(28, 1000, 4, darkBuildingMat, 0);
const midLayer = createCitySphere(20, 800, 7, buildingMat, 0);
const nearLayer = createCitySphere(12, 400, 10, buildingMat, 0);

cityGroup.add(distantLayer, midLayer, nearLayer);

// Glowing windows (instanced for performance)
const windowGeo = new THREE.PlaneGeometry(0.12, 0.08);
const windowMesh = new THREE.InstancedMesh(windowGeo, windowMat, 1500);
const wDummy = new THREE.Object3D();

for (let i = 0; i < 1500; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = 8 + Math.random() * 18;
  const y = -8 + Math.random() * 16;

  wDummy.position.set(
    Math.cos(angle) * radius,
    y,
    Math.sin(angle) * radius
  );
  wDummy.lookAt(0, y, 0);
  wDummy.updateMatrix();
  windowMesh.setMatrixAt(i, wDummy.matrix);
}
cityGroup.add(windowMesh);

// Traffic system
const trafficGroup = new THREE.Group();
scene.add(trafficGroup);

const shipGeo = new THREE.ConeGeometry(0.06, 0.25, 3);
// Handle geometry API for rotation
if (shipGeo.rotateX) {
  shipGeo.rotateX(Math.PI / 2);
} else if (shipGeo.vertices) {
  // Manual rotation for old Geometry
  for (let i = 0; i < shipGeo.vertices.length; i++) {
    const v = shipGeo.vertices[i];
    const y = v.y;
    v.y = v.z;
    v.z = -y;
  }
  shipGeo.verticesNeedUpdate = true;
}

const shipMat = new THREE.MeshStandardMaterial({
  color: 0xff6600,
  emissive: 0xff2200,
  emissiveIntensity: 3
});

const ships = [];
for (let i = 0; i < 60; i++) {
  const ship = new THREE.Mesh(shipGeo, shipMat);
  const radius = 7 + Math.random() * 16;
  const angle = Math.random() * Math.PI * 2;
  const height = -4 + Math.random() * 12;

  ship.position.set(
    Math.cos(angle) * radius,
    height,
    Math.sin(angle) * radius
  );

  ship.userData = {
    radius: radius,
    angle: angle,
    baseHeight: height,
    speed: 0.3 + Math.random() * 0.4,
    phase: Math.random() * Math.PI * 2
  };

  trafficGroup.add(ship);
  ships.push(ship);
}

// Atmospheric light shafts (additive transparency)
const shaftGeo = new THREE.CylinderGeometry(0.5, 3, 25, 16, 1, true);
const shaftMat = new THREE.MeshBasicMaterial({
  color: 0xaaccff,
  transparent: true,
  opacity: 0.04,
  side: THREE.DoubleSide,
  depthWrite: false,
  blending: THREE.AdditiveBlending
});

for (let i = 0; i < 6; i++) {
  const shaft = new THREE.Mesh(shaftGeo, shaftMat);
  shaft.position.set(
    (Math.random() - 0.5) * 30,
    5,
    (Math.random() - 0.5) * 30
  );
  shaft.rotation.x = (Math.random() - 0.5) * 0.4;
  shaft.rotation.z = (Math.random() - 0.5) * 0.4;
  cityGroup.add(shaft);
}

// Camera and controls
camera.position.set(18, 10, 18);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.3;
controls.minDistance = 8;
controls.maxDistance = 45;

// Animation
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  // Subtle city rotation
  cityGroup.rotation.y = t * 0.015;

  // Animate traffic in orbital lanes
  ships.forEach(ship => {
    const d = ship.userData;
    d.angle += d.speed * 0.008;
    const y = d.baseHeight + Math.sin(t * 0.5 + d.phase) * 0.8;

    ship.position.x = Math.cos(d.angle) * d.radius;
    ship.position.z = Math.sin(d.angle) * d.radius;
    ship.position.y = y;

    // Look ahead in orbit
    ship.lookAt(
      Math.cos(d.angle + 0.05) * d.radius,
      y,
      Math.sin(d.angle + 0.05) * d.radius
    );
  });

  // Dynamic lighting
  cityGlow.intensity = 0.9 + Math.sin(t * 0.7) * 0.25;
  windowMat.emissiveIntensity = 1.2 + Math.sin(t * 1.5) * 0.15;

  // Camera breathing
  camera.position.y += Math.sin(t * 0.3) * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

